  .plot("test-geom-dotplot.R: dodging works #1", p <- ggplot(dat, aes(x = x, y = y, fill = g)) +
      geom_dotplot(
        binwidth = 0.2,
        binaxis = "y",
        position = "dodge",
        stackdir = "center"
      ))
